<script>
import {markRaw} from 'vue'
import {Chart, registerables} from 'chart.js'
import {dataStore} from '@/operations/requests'
import {getManagerById} from '@/config/managers.config'

import MetricCard           from '@/components/others/MetricCard.vue'
import SummaryCardComponent from '@/components/others/SummaryCardComponent.vue'
import SupProdCards         from '@/components/others/SupProdCards.vue'
import SupProdChart    from '@/components/chart/SupProdChart.vue'
import SupProdHeatmap from '@/components/chart/SupProdHeatmap.vue'

Chart.register(...registerables)

function pctColor(p) {
  if (p >= 100) return '#22c55e'
  if (p >= 90)  return '#84cc16'
  if (p >= 80)  return '#f59e0b'
  if (p >= 70)  return '#f97316'
  return '#ef4444'
}

function fmtMln(v) {
  if (v == null) return '—'
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(2).replace('.', ',') + ' млн'
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(0) + ' тыс'
  return String(v)
}

function fmt(v) {
  if (v == null) return '—'
  return Math.round(v).toLocaleString('ru-RU')
}

const GAUGE_LEN = 110

const barLabelsPlugin = {
  id: 'storeBarLabels',
  afterDatasetsDraw(chart) {
    const {ctx: c, data} = chart
    const count = data.labels.length
    const small = count > 8

    chart.getDatasetMeta(0).data.forEach((bar, i) => {
      const pct   = data.datasets[2].data[i]
      const color = data.datasets[0].borderColor[i]
      const text  = pct + '%'
      c.save()
      c.font = `bold ${small ? 10 : 11}px system-ui`
      const tw = c.measureText(text).width + (small ? 10 : 14)
      const th = small ? 17 : 20, tx = bar.x, ty = bar.y + (small ? 14 : 18)
      c.beginPath(); c.fillStyle = color + 'dd'
      c.roundRect(tx - tw / 2, ty - th / 2, tw, th, th / 2); c.fill()
      c.fillStyle = '#fff'; c.textAlign = 'center'; c.textBaseline = 'middle'
      c.fillText(text, tx, ty); c.restore()

      if (!small || bar.width > 30) {
        c.save(); c.fillStyle = '#1e293b'
        c.font = `${small ? 500 : 600} ${small ? 9 : 11}px system-ui`
        c.textAlign = 'center'; c.textBaseline = 'bottom'
        c.fillText(fmtMln(data.datasets[0].data[i]), bar.x, bar.y - 4); c.restore()
      }
    })

    if (small) return

    chart.getDatasetMeta(1).data.forEach((bar, i) => {
      const pastVal = data.datasets[1].data[i]
      const factVal = data.datasets[0].data[i]
      c.save(); c.fillStyle = '#94a3b8'; c.font = '500 10px system-ui'
      c.textAlign = 'center'; c.textBaseline = 'bottom'
      c.fillText(fmtMln(pastVal), bar.x, bar.y - 24); c.restore()

      if (pastVal && factVal) {
        const growth  = Math.round(((factVal - pastVal) / pastVal) * 100)
        const isPos   = growth >= 0
        const text    = (isPos ? '▲ +' : '▼ ') + growth + '%'
        const color   = isPos ? '#16a34a' : '#dc2626'
        const bgColor = isPos ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)'
        c.save(); c.font = 'bold 10px system-ui'
        const tw = c.measureText(text).width + 10
        const th = 16, tx = bar.x, ty = bar.y - 6
        c.beginPath(); c.fillStyle = bgColor
        c.roundRect(tx - tw / 2, ty - th, tw, th, th / 2); c.fill()
        c.fillStyle = color; c.textAlign = 'center'; c.textBaseline = 'middle'
        c.fillText(text, tx, ty - th / 2); c.restore()
      }
    })
  },
}

export default {
  name: 'ManagerPage',
  components: {
    MetricCard,
    SummaryCardComponent,
    SupProdCards,
    SupProdChart,
    SupProdHeatmap,
  },
  props: {
    managerId: {type: String, required: true},
  },
  data() {
    return {
      isLoading:    true,
      periodOpen:   false,
      datePeriod:   [],
      userTimeDate: '',
      snackbar:      false,
      snackbarText:  '',
      reloadScheduled: false,
      GAUGE_LEN,
    }
  },
  created() { this._chart = null },

  computed: {
    config() {
      return getManagerById(this.managerId) || {name: '', color: '#94a3b8'}
    },
    allData() {
      return dataStore.getManagerData(this.managerId) || []
    },
    periodRows() {
      if (!this.userTimeDate) return []
      return this.allData.filter(row => row.time === this.userTimeDate)
    },
    currentRow()  { return this.periodRows[0] || null },
    storeRows()   { return this.periodRows.slice(1) },

    storesSortedByTO() {
      return this.storeRows.map(r => ({
        ...r, name: r.company,
        color: pctColor(r.products_p ? Math.round((r.products_f / r.products_p) * 1000) / 10 : 0),
        pctTO: r.products_p ? Math.round((r.products_f / r.products_p) * 1000) / 10 : 0,
      })).sort((a, b) => b.products_f - a.products_f)
    },

    storesSortedByTrafic() {
      return this.storeRows.map(r => ({
        ...r, name: r.company,
        pctTrafic: r.trafic_p ? Math.round((r.trafic_f / r.trafic_p) * 1000) / 10 : 0,
        yoyTrafic: r.trafic_past ? Math.round(((r.trafic_f - r.trafic_past) / r.trafic_past) * 100) : 0,
        color: pctColor(r.trafic_p ? Math.round((r.trafic_f / r.trafic_p) * 1000) / 10 : 0),
      })).sort((a, b) => b.trafic_f - a.trafic_f)
    },

    storesSortedByCheck() {
      return this.storeRows.map(r => ({
        ...r, name: r.company,
        pctCheck: r.check_p ? Math.round((r.check_f / r.check_p) * 1000) / 10 : 0,
        color: pctColor(r.check_p ? Math.round((r.check_f / r.check_p) * 1000) / 10 : 0),
      })).sort((a, b) => b.check_f - a.check_f)
    },

    maxCheck() {
      if (!this.storesSortedByCheck.length) return 1
      return Math.max(...this.storesSortedByCheck.flatMap(s => [s.check_f, s.check_p, s.check_past])) * 1.1
    },

    storesSortedByConver() {
      return this.storeRows.map(r => ({
        ...r, name: r.company,
        pctConver: r.conver_p ? Math.round((r.conver_f / r.conver_p) * 1000) / 10 : 0,
        color: pctColor(r.conver_p ? Math.round((r.conver_f / r.conver_p) * 1000) / 10 : 0),
      })).sort((a, b) => b.conver_f - a.conver_f)
    },

    maxConv() {
      if (!this.storesSortedByConver.length) return 20
      return Math.ceil(Math.max(...this.storesSortedByConver.flatMap(s => [s.conver_f, s.conver_p, s.conver_past])) * 1.2)
    },

    storesSortedByCredit() {
      return this.storeRows.map(r => ({
        ...r, name: r.company,
        pctCredit: r.credit_p ? Math.round((r.credit_f / r.credit_p) * 1000) / 10 : 0,
        color: pctColor(r.credit_p ? Math.round((r.credit_f / r.credit_p) * 1000) / 10 : 0),
      })).sort((a, b) => b.credit_f - a.credit_f)
    },

    maxCredit() {
      if (!this.storesSortedByCredit.length) return 50
      return Math.ceil(Math.max(...this.storesSortedByCredit.flatMap(s => [s.credit_f, s.credit_p])) * 1.3)
    },

    maxCount() {
      if (!this.storesSortedByCount.length) return 2
      return Math.max(...this.storesSortedByCount.flatMap(s => [s.count_f, s.count_p, s.count_past])) * 1.1
    },

    storesSortedByCount() {
      const result = this.storeRows.map(r => ({
        ...r, name: r.company,
        pctCount: r.count_p ? Math.round((r.count_f / r.count_p) * 1000) / 10 : 0,
        yoyCount: r.count_past ? Math.round(((r.count_f - r.count_past) / r.count_past) * 100) : 0,
        color: pctColor(r.count_p ? Math.round((r.count_f / r.count_p) * 1000) / 10 : 0),
      })).sort((a, b) => b.count_f - a.count_f)

      return result
    },


    // Итоговые строки менеджера по всем периодам (для тренд-чарта)
    managerPeriodTotals() {
      const seen = new Set()
      return this.allData.filter(r => {
        if (seen.has(r.time)) return false
        seen.add(r.time)
        return true
      })
    },

    supProdStoreItems() {
      return this.storeRows.map(r => ({
        name:     r.company,
        smart:    r.smart    ?? 0,
        note:     r.note     ?? 0,
        tv:       r.tv       ?? 0,
        sup_prod: r.sup_prod ?? 0,
        poslug:   r.poslug   ?? 0,
      }))
    },

  },

  mounted() {
    this.init()
    localStorage.setItem('checkLoadStatus', 'loaded')
  },

  beforeUnmount() {
    if (this._chart) { this._chart.destroy(); this._chart = null }
  },

  watch: {
    userTimeDate() {
      this.$nextTick(() => { this.refreshProductsChart() })
    },
  },

  methods: {
    async init() {
      let data = dataStore.getManagerData(this.managerId)

      if (!data || !data.length) {
        this.isLoading = true
        const manager  = this.config
        if (!manager?.url) { this.isLoading = false; return }

        try {
          const res      = await fetch(manager.url)
          const response = await res.json()
          dataStore.setManagerData(manager.id, response[manager.dataKey])
        } catch (err) {
          console.error(this.$t('common.errorManager'), err)
          this.snackbarText = this.$t('common.errorManager') + ' ' + manager.name + '. ' + this.$t('common.autoReload') + '...'
          this.snackbar     = true
          if (!this.reloadScheduled) {
            this.reloadScheduled = true
            setTimeout(() => window.location.reload(), 5000)
          }
        }

        data = dataStore.getManagerData(this.managerId)
      }

      if (!data || !data.length) { this.isLoading = false; return }

      const periods     = [...new Set(data.map(r => r.time))].reverse()
      this.datePeriod   = periods
      this.userTimeDate = periods[0] || ''
      this.isLoading    = false

      this.$nextTick(() => { this.initProductsChart() })
    },

    initProductsChart() {
      if (!this.$refs.productsCanvas) return
      const t = this.$t.bind(this)
      const ctx = this.$refs.productsCanvas.getContext('2d')
      this._chart = markRaw(new Chart(ctx, {
        data: {
          labels: [],
          datasets: [
            { type: 'bar',  label: this.$t('charts.factLabel'),     data: [], backgroundColor: [], borderColor: [], borderWidth: 2, borderRadius: 10, borderSkipped: false, yAxisID: 'yFact', order: 2 },
            { type: 'bar',  label: this.$t('charts.lastYearLabel'),  data: [], backgroundColor: 'rgba(148,163,184,0.3)', borderColor: 'rgba(148,163,184,0.65)', borderWidth: 2, borderRadius: 10, borderSkipped: false, yAxisID: 'yFact', order: 3 },
            { type: 'line', label: this.$t('charts.pctLabel'), data: [], borderColor: '#6366f1', backgroundColor: 'rgba(99,102,241,0.06)', borderWidth: 2.5, pointBackgroundColor: [], pointBorderColor: '#fff', pointBorderWidth: 2, pointRadius: 7, pointHoverRadius: 10, tension: 0.4, fill: true, yAxisID: 'yPct', order: 1 },
          ],
        },
        options: {
          responsive: true, maintainAspectRatio: false, animation: {duration: 500},
          interaction: {mode: 'index', intersect: false},
          plugins: {
            legend: {display: false},
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.92)', titleColor: '#e2e8f0', bodyColor: '#94a3b8',
              borderColor: 'rgba(255,255,255,0.08)', borderWidth: 1, padding: 14, cornerRadius: 12,
              callbacks: {
                label(ctx) {
                  if (ctx.datasetIndex === 0) return `  ${t('charts.factLabel')}: ${fmtMln(ctx.parsed.y)}`
                  if (ctx.datasetIndex === 1) {
                    const past = ctx.parsed.y, fact = ctx.chart.data.datasets[0].data[ctx.dataIndex]
                    const g = past ? Math.round(((fact - past) / past) * 100) : 0
                    return `  ${t('charts.lastYearLabel')}: ${fmtMln(past)}  (${g >= 0 ? '+' : ''}${g}% ${t('common.toLastYear')})`
                  }
                  return `  ${t('charts.pctLabel')}: ${ctx.parsed.y}%`
                },
              },
            },
          },
          scales: {
            x:     { grid: {display: false}, border: {display: false}, ticks: {color: '#64748b', font: {size: 12, weight: '600'}} },
            yFact: { type: 'linear', position: 'left',  grid: {color: 'rgba(148,163,184,0.12)'}, border: {display: false}, ticks: { color: '#64748b', font: {size: 11}, callback(v) { return v >= 1e6 ? (v/1e6).toFixed(1)+' млн' : v >= 1e3 ? (v/1e3).toFixed(0)+' тыс' : v } } },
            yPct:  { type: 'linear', position: 'right', min: 50, max: 150, grid: {display: false}, border: {display: false}, ticks: {color: '#6366f1', font: {size: 11}, callback: v => v + '%'} },
          },
        },
        plugins: [barLabelsPlugin],
      }))
      this.refreshProductsChart()
    },

    refreshProductsChart() {
      if (!this._chart) return
      const raw = this.storesSortedByTO
      if (!raw.length) return

      const ds = this._chart.data
      ds.labels                           = raw.map(s => s.name)
      ds.datasets[0].data                 = raw.map(s => s.products_f)
      ds.datasets[0].backgroundColor      = raw.map(s => s.color + 'bb')
      ds.datasets[0].borderColor          = raw.map(s => s.color)
      ds.datasets[1].data                 = raw.map(s => s.products_past)
      ds.datasets[2].data                 = raw.map(s => s.pctTO)
      ds.datasets[2].pointBackgroundColor = raw.map(s => s.color)
      this._chart.update('active')
    },

    barW(val, max)   { return Math.min((val / max) * 100, 100) + '%' },
    countBarW(val)   { return Math.min((val / this.maxCount) * 100, 100) + '%' },
    convLeft(val)    { return Math.min((val / this.maxConv) * 100, 100) + '%' },
    credW(val)       { return Math.min((val / this.maxCredit) * 100, 100) + '%' },
    gaugeOffset(pct) { return GAUGE_LEN - Math.min(pct / 150, 1) * GAUGE_LEN },

    // Для одиночного магазина
    metricClass(pct) {
      if (pct >= 100) return 'ss-metric--green'
      if (pct >= 85)  return 'ss-metric--yellow'
      return 'ss-metric--red'
    },
    yoyLabel(f, past) {
      if (!past) return '—'
      const pct = Math.round(((f - past) / past) * 100)
      return (pct >= 0 ? '▲ +' : '▼ ') + pct + '% ' + this.$t('common.toLastYear')
    },
    yoyClass(f, past) {
      if (!past) return ''
      return f >= past ? 'ss-yoy--green' : 'ss-yoy--red'
    },

    // i18n-aware форматтер для шаблона (млн/тыс/mln/k меняются с локалью)
    fmtMlnT(v) {
      if (v == null) return '—'
      if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(2).replace('.', ',') + '\u00a0' + this.$t('common.mln')
      if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(0) + '\u00a0' + this.$t('common.tys')
      return String(v)
    },

    pctColor, fmt, fmtMln,
  },
}
</script>

